from .tariffs import FIXED_MONTHLY_CHARGE, TIERS


def energy_charge(kwh: float) -> float:
    """Cost of `kwh` under the marginal tiers in tariffs.TIERS.

    Each tier applies only to the kWh within that tier's band (e.g. the
    first 100 kWh are billed at the first tier's rate, the next 200 at the
    second, and so on).
    """
    if kwh < 0:
        raise ValueError("kwh must be >= 0")
    total = 0.0
    previous_limit = 0.0
    for limit, rate in TIERS:
        if kwh <= previous_limit:
            break
        billed = min(kwh, limit) - previous_limit
        total += billed * rate
        previous_limit = limit
        if kwh <= limit:
            break
    return round(total, 2)


def monthly_bill(kwh: float) -> float:
    return round(FIXED_MONTHLY_CHARGE + energy_charge(kwh), 2)
